import { useState } from "react";
import {
  CreditCard,
  Zap,
  Gauge,
  Camera,
  Mail,
  Database,
  ExternalLink,
  ChevronDown,
  CheckCircle2,
  XCircle,
  AlertCircle,
  Lock,
  FlaskConical,
  Loader2,
  Info,
} from "lucide-react";
import { PageHeader } from "@/components/shared/PageHeader";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import { toast } from "sonner";
import { cn } from "@/lib/utils";

// ── Types ──────────────────────────────────────────────────────

type IntegrationStatus = "connected" | "server-side" | "missing";
type TestStatus = "idle" | "testing" | "success" | "failed";

interface EnvVar {
  name: string;
  description: string;
  resolved: boolean | null; // null = server-side (unknown)
}

interface SetupStep {
  n: number;
  text: React.ReactNode;
}

interface IntegrationDef {
  id: string;
  name: string;
  subtitle: string;
  category: string;
  description: string;
  status: IntegrationStatus;
  icon: React.ElementType;
  iconBg: string;
  iconColor: string;
  envVars: EnvVar[];
  usedBy: string[];
  setupSteps: SetupStep[];
  externalUrl?: string;
  externalLabel?: string;
}

// ── Status computation ─────────────────────────────────────────

const dodoStatus: IntegrationStatus = import.meta.env.VITE_DODO_PUBLISHABLE_KEY
  ? "connected"
  : "server-side";

const supabaseStatus: IntegrationStatus =
  import.meta.env.VITE_SUPABASE_URL && import.meta.env.VITE_SUPABASE_ANON_KEY
    ? "connected"
    : "missing";

// ── Integration definitions ────────────────────────────────────

const INTEGRATIONS: IntegrationDef[] = [
  {
    id: "dodo",
    name: "Dodo Payments",
    subtitle: "Subscriptions · Checkout · Webhooks",
    category: "Billing",
    description:
      "Processes all subscription payments, manages plan upgrades and downgrades, and handles invoice generation for Free, Pro, and Agency tiers.",
    status: dodoStatus,
    icon: CreditCard,
    iconBg: "bg-indigo-500/10",
    iconColor: "text-indigo-600",
    envVars: [
      {
        name: "DODO_SECRET_KEY",
        description: "Server-side secret key — used in dodo-checkout & dodo-portal edge functions",
        resolved: null,
      },
      {
        name: "DODO_WEBHOOK_SECRET",
        description: "Webhook signing secret — validates incoming Dodo Payments events",
        resolved: null,
      },
      {
        name: "DODO_PRICE_PRO_MONTHLY",
        description: "Product/Price ID for Pro monthly plan",
        resolved: null,
      },
      {
        name: "DODO_PRICE_AGENCY_MONTHLY",
        description: "Product/Price ID for Agency monthly plan",
        resolved: null,
      },
    ],
    usedBy: ["dodo-checkout", "dodo-portal"],
    setupSteps: [
      { n: 1, text: <>Go to <a href="https://dashboard.dodopayments.com" target="_blank" rel="noopener noreferrer" className="text-primary underline font-medium">dashboard.dodopayments.com</a> and copy your secret key</> },
      { n: 2, text: <>In Supabase Dashboard → <strong>Project Settings → Edge Functions → Secrets</strong>, add <code className="bg-background border border-border/60 px-1 py-0.5 rounded text-xs font-mono">DODO_SECRET_KEY</code> and <code className="bg-background border border-border/60 px-1 py-0.5 rounded text-xs font-mono">DODO_WEBHOOK_SECRET</code></> },
      { n: 3, text: <>Create webhook endpoint in Dodo dashboard pointing to your edge function URL</> },
      { n: 4, text: <>Add product IDs for Pro and Agency plans as <code className="bg-background border border-border/60 px-1 py-0.5 rounded text-xs font-mono">DODO_PRICE_PRO_MONTHLY</code> and <code className="bg-background border border-border/60 px-1 py-0.5 rounded text-xs font-mono">DODO_PRICE_AGENCY_MONTHLY</code></> },
    ],
    externalUrl: "https://dashboard.dodopayments.com",
    externalLabel: "Dodo Dashboard",
  },
  {
    id: "anthropic",
    name: "Anthropic Claude API",
    subtitle: "claude-sonnet-4-20250514 · Vision + Text analysis",
    category: "AI Engine",
    description:
      "Powers all 7 CRO pillar analyses using Vision (screenshot) + Text, generating scored findings and AI rewrite suggestions for every scan.",
    status: "server-side",
    icon: Zap,
    iconBg: "bg-purple-500/10",
    iconColor: "text-purple-600",
    envVars: [
      {
        name: "ANTHROPIC_API_KEY",
        description: "Claude API key — configured in Supabase Edge Function secrets",
        resolved: null,
      },
    ],
    usedBy: ["analyze-url"],
    setupSteps: [
      { n: 1, text: <>Go to <a href="https://console.anthropic.com/settings/keys" target="_blank" rel="noopener noreferrer" className="text-primary underline font-medium">console.anthropic.com</a> and create an API key</> },
      { n: 2, text: <>In Supabase Dashboard → <strong>Project Settings → Edge Functions → Secrets</strong></> },
      { n: 3, text: <>Add secret name <code className="bg-background border border-border/60 px-1 py-0.5 rounded text-xs font-mono">ANTHROPIC_API_KEY</code> and paste your key</> },
      { n: 4, text: "Deploy the analyze-url edge function — it will automatically pick up the new secret" },
    ],
    externalUrl: "https://console.anthropic.com",
    externalLabel: "Anthropic Console",
  },
  {
    id: "pagespeed",
    name: "Google PageSpeed Insights",
    subtitle: "Core Web Vitals · Performance scores",
    category: "Performance",
    description:
      "Provides Lighthouse-based performance scores, Core Web Vitals, and diagnostic metrics for the Page Performance CRO pillar (9% weight).",
    status: "server-side",
    icon: Gauge,
    iconBg: "bg-orange-500/10",
    iconColor: "text-orange-600",
    envVars: [
      {
        name: "PAGESPEED_API_KEY",
        description: "Google Cloud API key with PageSpeed Insights API enabled",
        resolved: null,
      },
    ],
    usedBy: ["pagespeed"],
    setupSteps: [
      { n: 1, text: <>Go to <a href="https://console.cloud.google.com/apis/credentials" target="_blank" rel="noopener noreferrer" className="text-primary underline font-medium">Google Cloud Console</a> → APIs & Services → Credentials</> },
      { n: 2, text: <>Create an API key and enable the <strong>PageSpeed Insights API</strong> for that key</> },
      { n: 3, text: <>In Supabase Dashboard → <strong>Project Settings → Edge Functions → Secrets</strong>, add <code className="bg-background border border-border/60 px-1 py-0.5 rounded text-xs font-mono">PAGESPEED_API_KEY</code></> },
    ],
    externalUrl: "https://console.cloud.google.com",
    externalLabel: "Google Cloud Console",
  },
  {
    id: "screenshot",
    name: "Screenshot Service",
    subtitle: "Puppeteer on Railway · Full-page captures",
    category: "Visual Analysis",
    description:
      "Captures full-page screenshots of scanned URLs via a Puppeteer microservice hosted on Railway. Screenshots are passed to Claude Vision for visual hierarchy analysis.",
    status: "server-side",
    icon: Camera,
    iconBg: "bg-sky-500/10",
    iconColor: "text-sky-600",
    envVars: [
      {
        name: "SCREENSHOT_SERVICE_URL",
        description: "Base URL of the Railway Puppeteer service",
        resolved: null,
      },
      {
        name: "SCREENSHOT_SERVICE_API_KEY",
        description: "Authentication key for the screenshot service",
        resolved: null,
      },
    ],
    usedBy: ["analyze-url"],
    setupSteps: [
      { n: 1, text: "Deploy the Puppeteer screenshot service to Railway (see /services/screenshot in the repo)" },
      { n: 2, text: <>Copy the Railway deployment URL and set it as <code className="bg-background border border-border/60 px-1 py-0.5 rounded text-xs font-mono">SCREENSHOT_SERVICE_URL</code></> },
      { n: 3, text: <>Generate a strong API key and add both secrets to Supabase Edge Function secrets</> },
    ],
  },
  {
    id: "resend",
    name: "Resend",
    subtitle: "Transactional email · Onboarding sequences",
    category: "Email",
    description:
      "Delivers scan completion notifications, plan upgrade confirmations, password resets, and onboarding email sequences.",
    status: "server-side",
    icon: Mail,
    iconBg: "bg-pink-500/10",
    iconColor: "text-pink-600",
    envVars: [
      {
        name: "RESEND_API_KEY",
        description: "Resend API key — set in Supabase Edge Function secrets",
        resolved: null,
      },
      {
        name: "SITE_URL",
        description: "Production site URL — used in email link generation",
        resolved: null,
      },
    ],
    usedBy: ["send-email"],
    setupSteps: [
      { n: 1, text: <>Go to <a href="https://resend.com/api-keys" target="_blank" rel="noopener noreferrer" className="text-primary underline font-medium">resend.com/api-keys</a> and create a new API key</> },
      { n: 2, text: "Add your sending domain to Resend and verify DNS records" },
      { n: 3, text: <>In Supabase Dashboard → <strong>Edge Functions → Secrets</strong>, add <code className="bg-background border border-border/60 px-1 py-0.5 rounded text-xs font-mono">RESEND_API_KEY</code> and <code className="bg-background border border-border/60 px-1 py-0.5 rounded text-xs font-mono">SITE_URL</code></> },
    ],
    externalUrl: "https://resend.com",
    externalLabel: "Resend Dashboard",
  },
  {
    id: "supabase",
    name: "Supabase",
    subtitle: "PostgreSQL · Auth · Storage · Edge Functions",
    category: "Infrastructure",
    description:
      "Core infrastructure — provides authentication (Google OAuth + email), PostgreSQL with RLS, Storage for screenshots, and Edge Function hosting for all backend logic.",
    status: supabaseStatus,
    icon: Database,
    iconBg: "bg-emerald-500/10",
    iconColor: "text-emerald-600",
    envVars: [
      {
        name: "VITE_SUPABASE_URL",
        description: "Project URL — found in Supabase Project Settings → API",
        resolved: Boolean(import.meta.env.VITE_SUPABASE_URL),
      },
      {
        name: "VITE_SUPABASE_ANON_KEY",
        description: "Anonymous public key — safe to expose in the browser",
        resolved: Boolean(import.meta.env.VITE_SUPABASE_ANON_KEY),
      },
      {
        name: "SUPABASE_SERVICE_ROLE_KEY",
        description: "Service role key — used in edge functions for admin operations",
        resolved: null,
      },
    ],
    usedBy: ["analyze-url", "pagespeed", "dodo-checkout", "dodo-webhook", "send-email"],
    setupSteps: [
      { n: 1, text: <>Create a project at <a href="https://supabase.com/dashboard" target="_blank" rel="noopener noreferrer" className="text-primary underline font-medium">supabase.com/dashboard</a></> },
      { n: 2, text: <>Copy Project URL and anon key from <strong>Project Settings → API</strong> into your <code className="bg-background border border-border/60 px-1 py-0.5 rounded text-xs font-mono">.env.local</code></> },
      { n: 3, text: "Run all database migrations via the Supabase CLI: npx supabase db push" },
      { n: 4, text: "Deploy edge functions: npx supabase functions deploy" },
    ],
    externalUrl: "https://supabase.com/dashboard",
    externalLabel: "Supabase Dashboard",
  },
];

// ── Style maps ─────────────────────────────────────────────────

const STATUS_CONFIG: Record<IntegrationStatus, { label: string; icon: React.ElementType; className: string }> = {
  connected: {
    label: "Connected",
    icon: CheckCircle2,
    className: "bg-green-100 text-green-700 border-0",
  },
  "server-side": {
    label: "Server-side",
    icon: AlertCircle,
    className: "bg-amber-100 text-amber-700 border-0",
  },
  missing: {
    label: "Not configured",
    icon: XCircle,
    className: "bg-red-100 text-red-700 border-0",
  },
};

const CATEGORY_BADGE: Record<string, string> = {
  Billing: "bg-indigo-100 text-indigo-700 border-0",
  "AI Engine": "bg-purple-100 text-purple-700 border-0",
  Performance: "bg-orange-100 text-orange-700 border-0",
  "Visual Analysis": "bg-sky-100 text-sky-700 border-0",
  Email: "bg-pink-100 text-pink-700 border-0",
  Infrastructure: "bg-emerald-100 text-emerald-700 border-0",
};

const TEST_STATUS_BADGE: Record<TestStatus, { label: string; className: string } | null> = {
  idle: null,
  testing: { label: "Testing…", className: "bg-muted/60 text-muted-foreground border-0 animate-pulse" },
  success: { label: "Connection OK", className: "bg-green-100 text-green-700 border-0" },
  failed: { label: "Test failed", className: "bg-red-100 text-red-700 border-0" },
};

// ── Sub-components ─────────────────────────────────────────────

function Step({ n, text }: { n: number; text: React.ReactNode }) {
  return (
    <div className="flex gap-3">
      <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-primary/10 text-[11px] font-semibold text-primary mt-0.5">
        {n}
      </span>
      <p className="text-sm text-muted-foreground leading-relaxed">{text}</p>
    </div>
  );
}

function EnvVarRow({ name, description, resolved }: EnvVar) {
  const isClientSide = resolved !== null;
  return (
    <div className="flex items-start justify-between gap-3 py-2.5">
      <div className="min-w-0">
        <code className="text-xs bg-muted/60 border border-border/40 px-1.5 py-0.5 rounded font-mono text-foreground/80">
          {name}
        </code>
        <p className="text-xs text-muted-foreground mt-1 leading-relaxed">{description}</p>
      </div>
      <div className="shrink-0 pt-0.5">
        {isClientSide ? (
          <Badge
            className={cn(
              "text-2xs px-1.5 py-0",
              resolved
                ? "bg-green-100 text-green-700 border-0"
                : "bg-red-100 text-red-700 border-0"
            )}
          >
            {resolved ? "Set" : "Missing"}
          </Badge>
        ) : (
          <div className="flex items-center gap-1">
            <Lock className="h-2.5 w-2.5 text-muted-foreground/50" />
            <span className="text-2xs text-muted-foreground/60">Secret</span>
          </div>
        )}
      </div>
    </div>
  );
}

function IntegrationRow({ integration }: { integration: IntegrationDef }) {
  const [open, setOpen] = useState(false);
  const [testStatus, setTestStatus] = useState<TestStatus>("idle");

  const { icon: Icon, status } = integration;
  const statusConfig = STATUS_CONFIG[status];
  const StatusIcon = statusConfig.icon;
  const categoryBadgeClass = CATEGORY_BADGE[integration.category] ?? "bg-muted/50 text-foreground/70 border-0";
  const testBadge = TEST_STATUS_BADGE[testStatus];

  const handleTest = () => {
    setTestStatus("testing");
    // Simulate a connection test (real implementation would call an edge function)
    setTimeout(() => {
      if (status === "missing") {
        setTestStatus("failed");
        toast.error(`${integration.name} not configured — set the required env vars first.`);
      } else {
        setTestStatus("success");
        toast.success(`${integration.name} connection verified.`);
      }
    }, 1400);
  };

  return (
    <Collapsible
      open={open}
      onOpenChange={setOpen}
      className="rounded-xl border border-border/50 bg-card overflow-hidden shadow-soft"
    >
      {/* ── Row header (always visible) ── */}
      <CollapsibleTrigger asChild>
        <button className="w-full flex items-center justify-between px-5 py-4 hover:bg-muted/30 transition-colors text-left group">
          <div className="flex items-center gap-3.5">
            {/* Service icon */}
            <div className={cn("h-10 w-10 rounded-lg flex items-center justify-center shrink-0", integration.iconBg)}>
              <Icon className={cn("h-5 w-5", integration.iconColor)} />
            </div>

            {/* Name + subtitle */}
            <div>
              <div className="flex items-center gap-2">
                <p className="text-sm font-semibold text-foreground leading-tight">
                  {integration.name}
                </p>
                <Badge className={cn("text-2xs px-1.5 py-0", categoryBadgeClass)}>
                  {integration.category}
                </Badge>
              </div>
              <p className="text-xs text-muted-foreground mt-0.5">{integration.subtitle}</p>
            </div>
          </div>

          {/* Status + chevron */}
          <div className="flex items-center gap-2.5 shrink-0">
            <Badge className={cn("text-xs px-2 py-0.5 flex items-center gap-1", statusConfig.className)}>
              <StatusIcon className="h-3 w-3" />
              {statusConfig.label}
            </Badge>
            <ChevronDown
              className={cn(
                "h-4 w-4 text-muted-foreground/60 transition-transform duration-200",
                open ? "rotate-180" : ""
              )}
            />
          </div>
        </button>
      </CollapsibleTrigger>

      {/* ── Expanded content ── */}
      <CollapsibleContent>
        <div className="px-5 pb-5 space-y-5">
          <Separator />

          {/* Description */}
          <p className="text-sm text-muted-foreground leading-relaxed">
            {integration.description}
          </p>

          {/* Env vars */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground/60 mb-2">
              Configuration
            </p>
            <div className="rounded-lg border border-border/50 divide-y divide-border/50 px-3">
              {integration.envVars.map((v) => (
                <EnvVarRow key={v.name} {...v} />
              ))}
            </div>
            <p className="text-xs text-muted-foreground/50 mt-2 flex items-center gap-1.5">
              <Lock className="h-3 w-3" />
              Server-side secrets are managed in Supabase Dashboard → Edge Functions → Secrets
            </p>
          </div>

          {/* Setup guide */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground/60 mb-3">
              Setup Guide
            </p>
            <div className="rounded-lg bg-muted/40 p-4 space-y-3">
              {integration.setupSteps.map((step) => (
                <Step key={step.n} n={step.n} text={step.text} />
              ))}
            </div>
          </div>

          {/* Used by */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground/60 mb-2">
              Used By
            </p>
            <div className="flex flex-wrap gap-1.5">
              {integration.usedBy.map((fn) => (
                <Badge
                  key={fn}
                  variant="outline"
                  className="text-xs font-mono border-border/60 text-muted-foreground"
                >
                  {fn}
                </Badge>
              ))}
            </div>
          </div>

          <Separator />

          {/* Footer actions */}
          <div className="flex items-center justify-between flex-wrap gap-3">
            <div className="flex items-center gap-2">
              {testBadge && (
                <Badge className={cn("text-xs", testBadge.className)}>
                  {testBadge.label}
                </Badge>
              )}
              {testStatus === "idle" && (
                <p className="text-xs text-muted-foreground">
                  Click "Test Connection" to verify the service is reachable.
                </p>
              )}
            </div>
            <div className="flex items-center gap-2 ml-auto">
              <Button
                variant="outline"
                size="sm"
                onClick={handleTest}
                disabled={testStatus === "testing"}
                className="text-xs border-border/60"
              >
                {testStatus === "testing" ? (
                  <Loader2 className="mr-1.5 h-3.5 w-3.5 animate-spin" />
                ) : (
                  <FlaskConical className="mr-1.5 h-3.5 w-3.5" />
                )}
                Test Connection
              </Button>
              {integration.externalUrl && (
                <Button variant="ghost" size="sm" asChild className="text-xs">
                  <a
                    href={integration.externalUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                  >
                    <ExternalLink className="mr-1.5 h-3.5 w-3.5" />
                    {integration.externalLabel ?? "Open Dashboard"}
                  </a>
                </Button>
              )}
            </div>
          </div>
        </div>
      </CollapsibleContent>
    </Collapsible>
  );
}

// ── Summary chip ───────────────────────────────────────────────

function SummaryChip({
  label,
  count,
  colorClass,
}: {
  label: string;
  count: number;
  colorClass: string;
}) {
  return (
    <div className={cn("flex items-center gap-2.5 rounded-lg border px-3 py-2.5", colorClass)}>
      <span className="text-xl font-bold tabular-nums">{count}</span>
      <span className="text-xs font-medium leading-tight">{label}</span>
    </div>
  );
}

// ── Main page ─────────────────────────────────────────────────

export default function AdminIntegrations() {
  const connectedCount = INTEGRATIONS.filter((i) => i.status === "connected").length;
  const serverSideCount = INTEGRATIONS.filter((i) => i.status === "server-side").length;
  const missingCount = INTEGRATIONS.filter((i) => i.status === "missing").length;

  return (
    <div className="space-y-6">
      <PageHeader
        title="Platform Integrations"
        description="Manage and monitor all external services connected to ConvertScan."
      />

      {/* Summary chips */}
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
        <SummaryChip
          label="Total"
          count={INTEGRATIONS.length}
          colorClass="border-border/50 bg-muted/30 text-foreground"
        />
        <SummaryChip
          label="Connected"
          count={connectedCount}
          colorClass="border-green-200 bg-green-50 text-green-800"
        />
        <SummaryChip
          label="Server-side"
          count={serverSideCount}
          colorClass="border-amber-200 bg-amber-50 text-amber-800"
        />
        <SummaryChip
          label="Not configured"
          count={missingCount}
          colorClass={
            missingCount > 0
              ? "border-red-200 bg-red-50 text-red-800"
              : "border-border/50 bg-muted/30 text-muted-foreground"
          }
        />
      </div>

      {/* Info banner */}
      <div
        role="note"
        className="flex items-start gap-3 rounded-xl border border-border/50 bg-muted/30 px-4 py-3.5"
      >
        <Info className="h-4 w-4 text-muted-foreground mt-0.5 shrink-0" />
        <p className="text-xs text-muted-foreground leading-relaxed">
          <span className="font-medium text-foreground">Server-side secrets</span> are stored in{" "}
          <strong>Supabase Dashboard → Project Settings → Edge Functions → Secrets</strong> and are
          never exposed to the browser. Click any integration row to view its setup guide and
          configuration details.
        </p>
      </div>

      {/* Integration rows */}
      <div className="space-y-3">
        {INTEGRATIONS.map((integration) => (
          <IntegrationRow key={integration.id} integration={integration} />
        ))}
      </div>
    </div>
  );
}

